import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_f32_tiled_32x32x64(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // Explicit register declarations for all named registers used
    .reg .pred %p0, %p1, %pRowIn, %pAg0In, %pAg1In, %pA0, %pA1, %pColIn, %pBg0In, %pBg1In, %pB0, %pB1, %pR, %pC, %pStore;
    .reg .b32 %rTx, %rTy, %rBx, %rBy, %r0, %r1, %rRow, %rCol, %rM, %rN, %rK, %rArowOffEl, %rAk0, %rAk1, %rBk0, %rBk1, %rAg0, %rAg1, %rBg0, %rBg1, %r2, %rTmp0, %rTmp1, %rkk, %rK0, %rBNc;
    .reg .b64 %rdA_param, %rdB_param, %rdC_param, %rdA, %rdB, %rdC, %rdSA, %rdSB, %rdArowOffB, %rdAsBase, %rdBcolOffB, %rdBsBase, %rdRowK, %rdBsKStep, %rdAg0_u64, %rdIdxA0, %rdByteA0, %rdPtrA0, %rdAk0B, %rdAsPtr0, %rdAg1_u64, %rdIdxA1, %rdByteA1, %rdPtrA1, %rdAk1B, %rdAsPtr1, %rdKgN0, %rdCol_u64, %rdIdxB0, %rdByteB0, %rdPtrB0, %rdBk0ElB, %rdBsPtr0, %rdKgN1, %rdCol_u64_1, %rdIdxB1, %rdByteB1, %rdPtrB1, %rdBk1ElB, %rdBsPtr1, %rdAsIter, %rdBsIter, %rdRowN, %rdCol64, %rdIdxC, %rdByteC, %rdPtrC;
    .reg .f32 %fAcc, %f0, %f1, %f2, %f3, %f4, %f5;
    .shared .align 16 .b8 sA[8192]; // 32*64*4
    .shared .align 16 .b8 sB[8192]; // 64*32*4
    // Load params and convert to global addresses
    ld.param.u64 %rdA_param, [A];
    ld.param.u64 %rdB_param, [B];
    ld.param.u64 %rdC_param, [C];
    ld.param.u32 %rM, [M];
    ld.param.u32 %rN, [N];
    ld.param.u32 %rK, [K];
    cvta.to.global.u64 %rdA, %rdA_param;
    cvta.to.global.u64 %rdB, %rdB_param;
    cvta.to.global.u64 %rdC, %rdC_param;
    // Thread/block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    // Compute output row/col
    mul.lo.u32 %r0, %rBy, 32;      // by * BM
    add.u32    %rRow, %r0, %rTy;   // row = by*BM + ty
    mul.lo.u32 %r1, %rBx, 32;      // bx * BN
    add.u32    %rCol, %r1, %rTx;   // col = bx*BN + tx
    // Accumulator
    mov.f32 %fAcc, 0f00000000;
    // Shared memory base pointers
    mov.u64 %rdSA, sA;
    mov.u64 %rdSB, sB;
    // Precompute base offsets for this thread in shared memory
    // A: row within the tile is ty, so base offset = ty * BK * sizeof(float)
    mul.lo.u32    %rArowOffEl, %rTy, 64;          // ty * BK
    mul.wide.u32  %rdArowOffB, %rArowOffEl, 4;    // bytes
    add.s64       %rdAsBase, %rdSA, %rdArowOffB;  // base ptr for A tile row (kk varying)
    // B: column within the tile is tx, so base offset = tx * sizeof(float)
    mul.wide.u32  %rdBcolOffB, %rTx, 4;
    add.s64       %rdBsBase, %rdSB, %rdBcolOffB;  // base ptr for B tile column (kk varying)
    // Global index base for A's row: row * K
    mul.wide.u32 %rdRowK, %rRow, %rK;
    // Constants
    // BN*4 (bytes to step one k in B shared memory)
    mov.u32 %rBNc, 32;
    mul.wide.u32 %rdBsKStep, %rBNc, 4; // 32*4 = 128 bytes
    // Loop over K tiles
    mov.u32 %rK0, 0;
$K_LOOP:
    setp.ge.u32 %p0, %rK0, %rK;
    @%p0 bra $K_DONE;
    // Compute local kk indices to load
    shl.b32 %r2, %rTx, 1;          // r2 = tx * 2
    mov.u32 %rAk0, %r2;            // kk for A load 0
    add.u32 %rAk1, %r2, 1;         // kk for A load 1
    mul.lo.u32 %rBk0, %rTy, 2;     // rBk0 = ty * 2
    add.u32 %rBk1, %rBk0, 1;       // rBk1 = ty * 2 + 1
    // Global k indices
    add.u32 %rAg0, %rAk0, %rK0;    // k_global A0
    add.u32 %rAg1, %rAk1, %rK0;    // k_global A1
    add.u32 %rBg0, %rBk0, %rK0;    // k_global B0
    add.u32 %rBg1, %rBk1, %rK0;    // k_global B1
    // Predicates for A loads: row < M and k < K
    setp.lt.u32 %pRowIn, %rRow, %rM;
    setp.lt.u32 %pAg0In, %rAg0, %rK;
    and.pred   %pA0, %pRowIn, %pAg0In;
    setp.lt.u32 %pAg1In, %rAg1, %rK;
    and.pred   %pA1, %pRowIn, %pAg1In;
    // Load/store A0
    @%pA0 cvt.u64.u32 %rdAg0_u64, %rAg0;
    @%pA0 add.s64     %rdIdxA0, %rdRowK, %rdAg0_u64;  // row*K + k
    @%pA0 shl.b64     %rdByteA0, %rdIdxA0, 2;         // *4
    @%pA0 add.s64     %rdPtrA0, %rdA, %rdByteA0;
    @%pA0 ld.global.f32 %f0, [%rdPtrA0];
    @!%pA0 mov.f32 %f0, 0f00000000;
    mul.wide.u32 %rdAk0B, %rAk0, 4;                // kk*4
    add.s64      %rdAsPtr0, %rdAsBase, %rdAk0B;    // sA[ty*BK + kk]
    st.shared.f32 [%rdAsPtr0], %f0;
    // Load/store A1
    @%pA1 cvt.u64.u32 %rdAg1_u64, %rAg1;
    @%pA1 add.s64     %rdIdxA1, %rdRowK, %rdAg1_u64;  // row*K + k
    @%pA1 shl.b64     %rdByteA1, %rdIdxA1, 2;         // *4
    @%pA1 add.s64     %rdPtrA1, %rdA, %rdByteA1;
    @%pA1 ld.global.f32 %f1, [%rdPtrA1];
    @!%pA1 mov.f32 %f1, 0f00000000;
    mul.wide.u32 %rdAk1B, %rAk1, 4;                // kk*4
    add.s64      %rdAsPtr1, %rdAsBase, %rdAk1B;    // sA[ty*BK + kk]
    st.shared.f32 [%rdAsPtr1], %f1;
    // Predicates for B loads: col < N and k < K
    setp.lt.u32 %pColIn, %rCol, %rN;
    setp.lt.u32 %pBg0In, %rBg0, %rK;
    and.pred   %pB0, %pColIn, %pBg0In;
    setp.lt.u32 %pBg1In, %rBg1, %rK;
    and.pred   %pB1, %pColIn, %pBg1In;
    // Load/store B0
    @%pB0 mul.wide.u32 %rdKgN0, %rBg0, %rN;          // k*N
    @%pB0 cvt.u64.u32  %rdCol_u64, %rCol;
    @%pB0 add.s64      %rdIdxB0, %rdKgN0, %rdCol_u64;// k*N + col
    @%pB0 shl.b64      %rdByteB0, %rdIdxB0, 2;       // *4
    @%pB0 add.s64      %rdPtrB0, %rdB, %rdByteB0;
    @%pB0 ld.global.f32 %f2, [%rdPtrB0];
    @!%pB0 mov.f32 %f2, 0f00000000;
    // sB[kk*BN + tx] offset for kk = rBk0
    mul.lo.u32   %rTmp0, %rBk0, 32;               // kk * BN
    mul.wide.u32 %rdBk0ElB, %rTmp0, 4;            // *4
    add.s64      %rdBsPtr0, %rdBsBase, %rdBk0ElB; // base + kk*BN*4 + tx*4
    st.shared.f32 [%rdBsPtr0], %f2;
    // Load/store B1
    @%pB1 mul.wide.u32 %rdKgN1, %rBg1, %rN;          // k*N
    @%pB1 cvt.u64.u32  %rdCol_u64_1, %rCol;
    @%pB1 add.s64      %rdIdxB1, %rdKgN1, %rdCol_u64_1;// k*N + col
    @%pB1 shl.b64      %rdByteB1, %rdIdxB1, 2;       // *4
    @%pB1 add.s64      %rdPtrB1, %rdB, %rdByteB1;
    @%pB1 ld.global.f32 %f3, [%rdPtrB1];
    @!%pB1 mov.f32 %f3, 0f00000000;
    mul.lo.u32   %rTmp1, %rBk1, 32;               // kk * BN
    mul.wide.u32 %rdBk1ElB, %rTmp1, 4;            // *4
    add.s64      %rdBsPtr1, %rdBsBase, %rdBk1ElB; // base + kk*BN*4 + tx*4
    st.shared.f32 [%rdBsPtr1], %f3;
    // Synchronize before compute
    bar.sync 0;
    // Iteration pointers for this tile
    mov.s64 %rdAsIter, %rdAsBase;                 // A: start at kk=0
    mov.s64 %rdBsIter, %rdBsBase;                 // B: start at kk=0
    // Inner loop over BK=64
    mov.u32 %rkk, 0;
$INNER_LOOP:
    setp.ge.u32 %p1, %rkk, 64;
    @%p1 bra $INNER_DONE;
    ld.shared.f32 %f4, [%rdAsIter];
    ld.shared.f32 %f5, [%rdBsIter];
    fma.rn.f32 %fAcc, %f4, %f5, %fAcc;
    // advance pointers
    add.s64 %rdAsIter, %rdAsIter, 4;              // next kk for A
    add.s64 %rdBsIter, %rdBsIter, %rdBsKStep;     // next kk for B (BN*4 bytes)
    add.u32 %rkk, %rkk, 1;
    bra $INNER_LOOP;
$INNER_DONE:
    // Synchronize before next tile
    bar.sync 0;
    // Next K tile
    add.u32 %rK0, %rK0, 64;
    bra $K_LOOP;
$K_DONE:
    // Store result if within bounds
    setp.lt.u32 %pR, %rRow, %rM;
    setp.lt.u32 %pC, %rCol, %rN;
    and.pred %pStore, %pR, %pC;
    @%pStore mul.wide.u32 %rdRowN, %rRow, %rN;         // row*N
    @%pStore cvt.u64.u32  %rdCol64, %rCol;
    @%pStore add.s64      %rdIdxC, %rdRowN, %rdCol64;  // row*N + col
    @%pStore shl.b64      %rdByteC, %rdIdxC, 2;        // *4
    @%pStore add.s64      %rdPtrC, %rdC, %rdByteC;
    @%pStore st.global.f32 [%rdPtrC], %fAcc;
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_f32_tiled_32x32x64")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.size(0))
        K = int(A.size(1))
        N = int(B.size(1))
        C = torch.empty((M, N), device=A.device, dtype=A.dtype)

        grid_x = (N + 32 - 1) // 32
        grid_y = (M + 32 - 1) // 32

        module = _get_ptx_module()
        module.launch(
            "matmul_f32_tiled_32x32x64",
            grid=(grid_x, grid_y, 1),
            block=(32, 32, 1),
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

